import{_ as e,H as a,f as _,i as p}from"./chunks/framework.BH2BK_3i.js";const l=JSON.parse('{"title":"导学（三）| 一个CPU是怎么寻址的？","description":"","frontmatter":{},"headers":[],"relativePath":"编程高手必学的内存知识/导学（三）-一个CPU是怎么寻址的？.md","filePath":"编程高手必学的内存知识/导学（三）-一个CPU是怎么寻址的？.md","lastUpdated":1779821602000}'),r={name:"编程高手必学的内存知识/导学（三）-一个CPU是怎么寻址的？.md"};function n(o,t,C,s,i,c){return a(),_("div",null,[...t[0]||(t[0]=[p('<h1 id="导学-三-一个cpu是怎么寻址的" tabindex="-1">导学（三）| 一个CPU是怎么寻址的？ <a class="header-anchor" href="#导学-三-一个cpu是怎么寻址的" aria-label="Permalink to &quot;导学（三）| 一个CPU是怎么寻址的？&quot;">​</a></h1><p>你好，我是海纳。</p><p>这是我们导学的第三节课，我们一起来探寻一个CPU是怎么寻址的。这节课是以视频形式讲述的，内容比较多，但都是纯干货，非常值得你花时间好好观看学习。</p><p>我们知道，CPU的设计思路大致分为两个流派，一个是复杂指令集（Complex Instruction Set Computing， CISC）；另一个是精简指令集（Reduced Instruction Set Computing，RISC），前者的代表是 X86，后者的代表是 Arm 和 RISC-V。</p><p>其中，RISC 的特点是指令长度短，运行速度快，但每条指令能做的事情比较少；CISC 的特点是指令长度长，运行速度慢，但指令能做的事情多。相同的C代码要是翻译成RISC指令，往往会比 CISC 最终翻译出的二进制文件的体积更大。这节课，我会帮你理清CISC和RISC指令的区别。</p><p>此外，我还会给你深入讲解寻址模式。寻址就是在程序中如何定位地址，我们可以把它类比成现实生活中在地图上定位某个地址的过程。这也是你在学习内存管理时的必备知识。</p><p>好，现在就请你点开下面的视频，来学习今天的课程吧！</p><p>点击 <a href="https://pan.baidu.com/s/1565zP07nd69UQHOxupPktQ" target="_blank" rel="noreferrer">这里</a> 获取课件，提取码：hn66。</p>',8)])])}const u=e(r,[["render",n]]);export{l as __pageData,u as default};
